-- Project codes are generated by the system (CEC-PRJ-YYMM-NNN) and cannot be edited afterwards.
create or replace function public.lock_project_code() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.code is distinct from old.code then raise exception 'كود المشروع يتولد تلقائياً وما ينعدل'; end if;
  return new;
end $$;
create trigger projects_code_locked before update on public.projects for each row execute function public.lock_project_code();
